import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { registerSW } from 'virtual:pwa-register';
import App from './App';
import { purgeLegacyData } from './state/persist';
import './styles/global.css';

// Offline support + installability (service worker generated by vite-plugin-pwa).
registerSW({ immediate: true });

// Drop demo data that older builds stored on this device.
purgeLegacyData();

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);
